// This file derives HTTP response details shared by the OpenAPI 2 and OpenAPI
// 3 generators. The shared Error schema stays reusable while each response
// shows the exact flags generated by its service constructor.
package openapi

import "goa.design/goa/v3/expr"

// ResponseContentType returns the content type used for one HTTP response. A
// response setting wins, followed by its result type and application/json.
func ResponseContentType(response *expr.HTTPResponseExpr) string {
	if response.ContentType != "" {
		return response.ContentType
	}
	if result, ok := response.Body.Type.(*expr.ResultTypeExpr); ok && result.ContentType != "" {
		return result.ContentType
	}
	return "application/json"
}

// ErrorResponseExample returns the generated body example for one use of
// Goa's built-in error result. It returns false when the error uses another
// type, supplies an authored example, or suppresses generated examples.
func ErrorResponseExample(errorExpression *expr.ErrorExpr, body *expr.AttributeExpr, generator *expr.ExampleGenerator, values Values) (any, bool) {
	if !expr.IsErrorResult(errorExpression.Type) || len(values.Examples(body, body.ExtractUserExamples())) > 0 {
		return nil, false
	}
	example := ProjectExample(body, values.Example(body, generator))
	if example == nil {
		return nil, false
	}
	object, ok := example.(map[string]any)
	if !ok {
		return example, true
	}
	setExampleField(object, "name", errorExpression.Name)
	_, temporary := errorExpression.Meta["goa:error:temporary"]
	_, timeout := errorExpression.Meta["goa:error:timeout"]
	_, fault := errorExpression.Meta["goa:error:fault"]
	setExampleField(object, "temporary", temporary)
	setExampleField(object, "timeout", timeout)
	setExampleField(object, "fault", fault)
	return object, true
}

// setExampleField changes a field only when that field is part of the HTTP
// response body. Fields mapped to headers or cookies are not added back.
func setExampleField(example map[string]any, name string, value any) {
	if _, ok := example[name]; ok {
		example[name] = value
	}
}
